import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Rho status","description":"","frontmatter":{},"headers":[],"relativePath":"reference/status.md","filePath":"reference/status.md"}'),n={name:"reference/status.md"};function r(i,e,d,h,c,l){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="rho-status" tabindex="-1">Rho status <a class="header-anchor" href="#rho-status" aria-label="Permalink to &quot;Rho status&quot;">​</a></h1><p>Updated: 2026-11-05.</p><h2 id="current-focus" tabindex="-1">Current focus <a class="header-anchor" href="#current-focus" aria-label="Permalink to &quot;Current focus&quot;">​</a></h2><p><a href="/Rho/docs/records/dsh-rho-episode#conversation-project-matching">dsh-rho 0.1.4</a> binds each conversation’s tools and launcher to the same verified project folder. Six regressions, two real services and the original Desktop conversation pass; the local plugin is upgraded. The <a href="https://yulab-smu.top/Rho/market/index.json" target="_blank" rel="noreferrer">public market</a> selects the same prebuilt 0.1.4 from a fixed source commit; this is Rho’s own index, added explicitly in Harness. Result review, historical evidence, macOS 0.5.1 and the offline reader retain their <a href="/Rho/docs/records/review-evidence-episode">episode</a>. Native tools remain normal; Core is optional. No Core execution behavior changed. <a href="/Rho/docs/records/p3-continuity-episode">P3 continuity</a> reproduced a 64-turn stop and continued it after reopening; the restarted Notebook&#39;s in-memory state did not survive, and four native choices remained. Claude sessions now prefer Auto, and Rho sets no step or wall cap by default. Rerun so, P3 asked for no permission; the Agent&#39;s MCP bridge had cut Notebook calls at 30 s and then 300 s, and without those cuts P3 finished in the shared R session in 12.9 minutes.</p><p>The <a href="https://github.com/YuLab-SMU/Rho-paper" target="_blank" rel="noreferrer">research method proposal</a> centers on purpose-driven composition: selecting materials, arranging related views and operations, and carrying their meaning into Agent continuation. Plugins supply information, compute and environment capabilities. The single-cell walkthrough distinguishes scientific purposes and how inputs and execution conditions change the workspace. Galaxy and JupyterLab constrain plugin-related novelty alongside interface and shared-context comparisons. Remote connections remain illustrative; novelty and human benefits are not established by existing Rho checks.</p><table tabindex="0"><thead><tr><th>Part</th><th>Current behavior</th><th>Evidence or remaining work</th></tr></thead><tbody><tr><td>Immutable capture</td><td>Files snapshots survive original overwrite/deletion; disk and dirty buffer versions differ; server-side new-turn collection has budgets/gaps</td><td>Owner and conversation fault tests; no retrospective reconstruction</td></tr><tr><td>Result review</td><td>Row/range/resource questions, explicit replies, multi-field keyed differences, code changes and human decisions</td><td>Real airquality and browser trials; new versions need a new decision</td></tr><tr><td>Agent feedback</td><td>Frozen contexts join message identities; direct sends are separate from deciding; external handoff copies</td><td>Real Claude and Codex trials; context fetch differs from explicit reply</td></tr><tr><td>Graph</td><td>Exact captured refs and capture times, current-file action separate, honest reported/named/observed links, bounded focus</td><td>Same-path versions and 160-node-cap regressions; old records show gaps</td></tr><tr><td>Offline evidence</td><td>Preview one review and explicit refs; static reader/original files/manifest; read-only verifier</td><td>Service closed/project moved; four browser widths; tamper detection</td></tr><tr><td>macOS 0.5.1</td><td>Unsigned npm tarball/local WebUI selected; Core bundled explicitly</td><td><a href="/Rho/docs/records/preview-0-5-1">Fixed tarball installed and exercised</a></td></tr><tr><td>0.5.2 candidate</td><td>16 MB tarball for macOS arm64 and Linux x64/arm64, and a 12 MB Windows x64 one: one Core per platform (Core <code>c3dbeca</code>), Claude Code/Codex the person&#39;s own, all 12 plugins</td><td><a href="/Rho/docs/records/package-0-5-2-episode">Packing, real Claude/Codex</a>; <a href="/Rho/docs/records/platforms-0-5-2-episode">offline install on four systems, Linux Notebook and Open folder</a>; <a href="/Rho/docs/records/windows-0-5-2-episode">Windows: Host lifetime and stop, installed checks</a>; x64 only under Rosetta; the full 0.5.1 acceptance not done</td></tr><tr><td>CI and npm</td><td>Each push that changes more than documentation builds the four Cores (each Core commit once), runs the suite on macOS, Linux and Windows, packs one candidate for all four platforms (3,030 files, 23 MB; bundled third-party packages keep what Node loads, licenses and reached declarations) and installs it offline on each; a <code>v*</code> tag publishes the candidate CI tested for that commit as <code>@rho-workspace/rho</code>, building nothing</td><td><a href="/Rho/docs/records/ci-episode">CI episode</a>: every job passes on the four platforms since run 7; <a href="/Rho/docs/records/ci-episode#publication"><code>@rho-workspace/rho@0.5.4</code></a> published on 2026-11-05 from the candidate CI run 41975339969 tested, with provenance and its README, declaring <code>&gt;=22.22.0 &lt;27</code>; npm served it 55 minutes after accepting it, byte-identical to that candidate, and Linux x64 also installs it on Node 24 and 26; CI failed from <code>e92efb12</code> until <code>826d73c1</code> selected the Plugins commit the Data flow imports; pruning cut the Windows offline install by 35–39%</td></tr><tr><td>Independent researcher use</td><td>Unobserved</td><td>Trial guide in the episode; no usability claim</td></tr><tr><td>Example project</td><td><code>example/pa14-qs</code> ships with the application; a new state copies it into the projects folder once, as an ordinary editable project</td><td><a href="/Rho/docs/records/example-project-episode">Episode</a>. Without folders (after 0.5.3), <code>npx @rho-workspace/rho</code> starts on <code>~/Rho/projects</code> and <code>~/Rho/state</code>, ships this project, and names a missing Agent client or R at startup; flagged starts are unchanged. The full suite also passes on Node 18.20.8 (end of life), below the engine range&#39;s 22.22.</td></tr><tr><td>dsh-rho 0.1.4</td><td>Prebuilt public Git package and Rho’s own market index; each conversation’s tools and launcher select the same verified folder; <a href="/Rho/docs/reference/deepseek-harness">installation and upgrade guide</a></td><td><a href="/Rho/docs/records/dsh-rho-episode#public-workspace-fix">Public workspace fix</a>: the fixed source installed in two fresh Harness 0.2.1-rc.5 profiles, with and without scripts; all nine package files match; 6/6 adapter tests and earlier real MCP/Desktop project checks. No npm, default-source, TUI or other OS claim</td></tr><tr><td>Literature reproduction</td><td>Five papers of the 97 fully-open corpus reproduced in Rho 0.5.2 (bulk, snRNA-seq, GeoMx DSP, bulk+metabolome, multi-omics): Agents ran R in the shared Notebook, Rho captured cells, values, figures and notes</td><td><a href="/Rho/docs/records/literature-repro-episode">Episode</a>: two of five needed one turn and three needed 2–4, because the Agent client capped at 64 turns or waited on an event nothing wakes; 8–24 approval choices per run (counted); resource paths guessed. Conversation return and turn-limit continuation have a later <a href="/Rho/docs/records/p3-continuity-episode">P3 pass</a>; the other issues remain.</td></tr><tr><td>Agent practice Skill</td><td><code>rho.analysis-run</code> 1.1 is a shipped Skill for running a whole analysis in the live sessions, and every conversation started here is told to read it before a multi-step analysis</td><td>Written from the five reproductions above: spend calls on the analysis not on re-discovery, never wait for an event that does not come, draw to an explicit device, write files complete and to disk, and report the state actually reached. Read back through <code>skill.list</code>/<code>skill.read</code> on a running service; <code>test:notebook</code> is its verify command</td></tr><tr><td>Agent setup</td><td>A person asks their Agent to read <a href="https://yulab-smu.top/Rho/doc/setup.md" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/doc/setup.md</a> (<a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/../SETUP.md" target="_blank" rel="noreferrer">SETUP.md</a>); the Agent installs the npm package, starts Rho on <code>~/Rho/projects</code> and <code>~/Rho/state</code>, installs the Agent Skill <code>skills/rho</code> in its own skills folder and connects itself to the example project</td><td><a href="/Rho/docs/records/docs-site-episode#setup-page-and-agent-skill">Episode</a>: the skill was checked against npm 0.5.3, and one fresh Claude Code session used it in the Notebook with no refusals; the page was followed by hand on 0.5.3 in a throwaway home, including the Claude Code and Codex configuration; <a href="/Rho/docs/records/docs-site-episode#the-latest-page-and-skill-and-the-node-row">on the site</a> the page and the skill&#39;s eight files answer 200, byte-identical to <code>f82bc77a</code>; no Agent has yet followed it from the one-sentence prompt; Windows was not run</td></tr><tr><td>Documentation site</td><td><a href="https://yulab-smu.top/Rho/" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/</a> is a front page with the real WebUI replaying the shipped PA14 project&#39;s recorded session (no backend), the one install sentence that sends an Agent to the setup page, and the recorded and per-plugin example prompts, with no desktop installers until a current desktop release; <code>docs/</code> is published under <code>/docs/</code> with local search and every page naming its source file</td><td><a href="/Rho/docs/records/docs-site-episode">Episode</a>: the demo tour gets every request answered at 1440 and 390 px; the install prompts&#39; commands ran on npm 0.5.3, and the front page now gives <a href="/Rho/docs/records/docs-site-episode#the-front-page-asks-for-the-sentence">the sentence</a> instead; <a href="/Rho/docs/records/docs-site-episode#the-install-prompt-on-a-real-machine">one Codex run</a> stopped at the Node check, lost its background start and exposed a port that moved per start, Codex grants shown as Claude Code&#39;s and stack-trace refusals, fixed in Rho; the prompts are unchanged; the four <code>updates/*.json</code> feeds are unchanged; the documentation, redeployed from <code>2d97d763</code>, names the registry&#39;s version and the Node range (<a href="/Rho/docs/records/docs-site-episode#the-documentation-for-0-5-4">0.5.4</a>); the demo is still the earlier build; no outside reader yet</td></tr><tr><td>Python environments</td><td>An Agent makes an environment in the project and passes <code>interpreter</code> (<code>.venv/bin/python</code>) to <code>kernel.run</code> (Notebook 0.5.3); the project keeps it for that language, a session only the Agent used starts again with it, and each session and cell records its program and version; the Agent panel reads install commands as what they installed</td><td><a href="/Rho/docs/records/python-env-episode">Episode</a>: five real runs outside Rho and from its Agent panel; installs made inside cells are not read as installs; other models and Codex unobserved</td></tr><tr><td>Variable relations</td><td>Under each Notebook cell, what it read and from which cell, and the later cells that read what it made; Variables names the cell that made each value and those that read it; Data flow is a graph of values from the files read to the results written or plotted, each node titled with the meaning the code&#39;s <code># means:</code> comment gives (the Agent writes these; read from the text, never run), with functions and constants named on what uses them, a bar to trace one result, and the chosen value&#39;s path and details; beside a script&#39;s editor it is read from the text (R and Python) and marks the lines behind and in front of the chosen value (Notebook 0.5.5, Documents 0.4.11)</td><td><a href="/Rho/docs/records/variable-flow-episode#redesign-a-graph-of-values">Episode</a> and <a href="/Rho/docs/records/variable-flow-episode#meaning-in-the-code">meanings</a>: redesigned after the user judged the boxes useless; the shipped example in a real browser at 1440, 1920 and 390 px; with comments written by hand, the editor shows 13 of 19 values with a meaning, and a fresh Agent run&#39;s script reads as 6 of 7 values and both written files; read, not run, so names built at run time, dplyr columns named like a value and pasted paths are missed; the meanings are the Agent&#39;s words and no person has used them</td></tr></tbody></table><p>M0 retains Python/R highlighting, Markdown reading and native command exit/time/bounded output (<a href="/Rho/docs/records/code-markdown-episode">record</a>); its report trial keeps scripts, results and report after originals change. A first Codex feedback attempt cancelled by the acceptance&#39;s permission selector stays recorded beside the corrected trial; Annotations 0.5.1 keeps a new Review conversation for later feedback. Installed Codex needed a selected 64-choice native permission budget (default 32); its grant scope did not change.</p><p>A <a href="/Rho/docs/records/simulated-project-episode">simulated-project episode</a> ran two rho-bio-eval capsule projects through Rho with Claude Code and changed what their screens showed: Studio&#39;s eight-view budget now renders the views on screen first, Overview opens with the latest answer, the Graph folds a message&#39;s versions of one file and its unrelated commands, Review (Annotations 0.5.2) offers questions and kept results as choices, a folder chosen in the system dialog stays in the local person&#39;s list across restarts, and a tab on this machine names its principal again, so the person&#39;s own edits read &quot;You&quot;. Row questions on an ordinary CSV still need an identity choice (a declared key column or a row position within one exact version); projects and conversations now have addresses, while other pages do not.</p><p>Its <a href="/Rho/docs/records/simulated-project-episode#second-pass">second pass</a> moved review onto the answer. The Overview leads with an answer board derived from the Graph: results by role, then method, run, inputs and report. Ask on a result or a selected passage continues the same conversation, and later questions stay with the answer they ask about. Use this answer or Needs changes (<code>conversation.decide</code>) is bound to the versions the message kept. Review is listed only while review records exist. The Console (Console 0.1.0) lists the Agent&#39;s and the person&#39;s commands, and runs, stops and reruns the person&#39;s own (local browser only). A message&#39;s commands read in the order they ran, each led by the Agent&#39;s own words on what it was for (Agent 0.4.23). Agent 0.4.19 keeps a command&#39;s whole text. Repeated reads no longer exhaust a message&#39;s capture budget before its results. Agent-declared choices are shown by the meaning layer pass below, without Agree/No.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#process-studio">process Studio</a> pass made Studio show how a conversation&#39;s work was done. Each conversation started in Rho has its own Studio, laid out from its record by role: data, script and a Commands view down one side, figures above tables and reports on the other, each file&#39;s view naming the kept version it shows. A chip names the part of the work in progress, and a timeline runs beside the Agent panel. A moment chosen there replays the views, commands, part and conversation together. Arranging saves the layout as <code>conversation-&lt;id&gt;</code>. The person&#39;s own workspace still opens nothing by itself.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#project-notes">project notes</a> pass lists the sessions under Studio in the sidebar, then the person&#39;s workspaces, and shares one set of notes (<code>project-notes.md</code>) beside every Studio layout. Rho asks each session it starts, in its Agent&#39;s instructions (Agent 0.4.20), to keep one section: a heading naming its task with its session marker, then Question, Data &amp; method, Key results with a figure and To do. That heading titles the session. In a live run Claude Code (DeepSeek V4.1 Flash) wrote its section unprompted by the message, and the title followed within seconds. The panel reads the notes formatted, ticks to-dos in place and edits them with a toolbar (Markdown 0.2.0, Documents 0.4.8); the person&#39;s edits save after a pause.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#meaning-layer">meaning layer</a> pass reads each section of the notes as a question, method, findings, figures, choices, file descriptions and to-dos, each with the files it links. Kept versions of the notes trace a statement to the message that wrote it and each file to the version kept then. The Graph shows Meaning + process by default, or either layer alone, with &quot;kept as&quot; and &quot;written in&quot; edges into the process. The answer board and Studio&#39;s file views say what each file holds. A choice shows what it is about and what was taken, with any other option the notes name under it, nested or in the same sentence, and what it gives; Use this instead drafts a message, and nothing waits on the person. The Agent followed the fixed subsections, linked its files and computed some alternatives, but described files at the end of its run, not as it wrote them, even when told to.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#descriptions-while-the-work-goes-on">descriptions</a> pass reads each file a running message writes: facts from its bytes within seconds, then one sentence from the conversation&#39;s model through the person&#39;s own Claude Code with no tools (Agent 0.4.22). Studio, the answer board and the Graph show the notes&#39; words first, then the sentence with its model, then the facts. In two live runs, results had facts within 6 s of being written and sentences within half a minute (10 s median in the first). <a href="/Rho/docs/records/simulated-project-episode#figures-cost-and-a-switch">Figures</a> go to the model as images when models.dev lists it as reading them, else as the code that made them. Each call is priced by Claude Code or from models.dev&#39;s price; the session popover shows the conversation&#39;s spend and a person-wide switch. In the ninth copy, 13 calls cost about $0.0086, and the first image sentence misnamed the plot type.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#quick-checks-choices-and-the-console">quick checks</a> from rho-bio-eval ran in Rho: bix-18 (Python) had 4 of 5 answers in range twice, the miss being a proportion against a range written as a percentage; bix-51 (R) had 7 of 7. The Choices and the Console were redrawn from what these runs showed.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#the-notebook">Notebook</a> (Notebook 0.1.0) keeps a live R and a live Python session per project that the person shares with the Agent. Its page lists cells in the order they ran with who ran them and why, the code, output streamed as it is printed with messages and warnings in place, plots, and the session&#39;s variables; the person runs, edits, reruns and interrupts cells, and only they stop a session. A conversation&#39;s Studio shows the cells its Agent ran. In fresh quick checks the Agent ran its script in the session (bix-51 7 of 7 in 5 cells, bix-18 4 of 5 in 4 cells) rather than exploring cell by cell. The default Agent grant had reached its 64-method limit, so the limit is now 96 (<code>layeredGrantLimits.maxMethods</code>); a larger grant is still refused.</p><p>The Notebook is also a view of any Studio page (<a href="/Rho/docs/records/simulated-project-episode#exploring-a-finished-answer">episode</a>). The person makes empty workspaces of their own and adds the Notebook or project files to them. Explore in R or Python on a table or script, from Studio, the answer board or the file page, opens it on their workspace beside the Notebook: a table loads as a new value in their own cell, a script waits in the line to run. A Studio stage under 640 px shows its views one at a time. Pages cannot yet be renamed or removed.</p><p>Values of the live sessions have a view of their own (<a href="/Rho/docs/records/simulated-project-episode#looking-at-values">episode</a>). Notebook&#39;s <code>kernel.inspect</code> reads one value as its session describes it, without starting, waiting for or changing a session; each cell names the values it made, changed and removed. From the Notebook&#39;s variables or a cell&#39;s names the value opens beside the Notebook, or as a tab next to it when a split would leave either under 360 px: a table pages, sorts and gives each column&#39;s type and summary; a model its fit and coefficients; a list its parts, each opening in place with the code that reaches it, which Use in Notebook puts in the line. While a cell runs or after the value is gone, the last reading stays, dimmed, with the cell it was read after.</p><p>The four panes of interactive exploration, a script, its console, the variables and the plots, are made from these components (<a href="/Rho/docs/records/simulated-project-episode#script-console-variables-and-plots">episode</a>). ⌘/Ctrl+Enter or Run in an R or Python script runs the selection, or the statement the cursor is in, as the person&#39;s cell and moves on; a page without the Notebook gets one under the script. Variables and Plots are views of their own, in a column along the page&#39;s right side. R now draws on one device for the whole session, so a later cell draws over an earlier plot and a sourced script keeps each plot. No Agent ran cells in this layout.</p><p>The Notebook has <a href="/Rho/docs/records/simulated-project-episode#two-forms-of-the-notebook">two forms</a> of the same sessions, switched in its header: the notebook, and a console with one transcript of prompts and output, Enter that runs finished code and continues unfinished code, history, Esc and Clear. A Studio view saves its form with the page; one placed by running a script&#39;s line starts as a console.</p><p><a href="/Rho/docs/records/simulated-project-episode#toolbars">Toolbars</a> take one form whichever component puts a control in a view&#39;s header: quiet words and icons, Run in the accent, one kind of switch, and a control only while it can act (Documents 0.4.9: Save with unsaved edits, Review with a selection, Highlight changes while Agent or disk edits remain). The Activity row joined the Studio bar, so the code starts 72 px higher at 1440 × 900.</p><p><a href="/Rho/docs/records/agent-canvas-episode#the-person-s-own-hands-on-the-layout">By hand</a>, the person arranges Studio as the Agent does: × on the shown tab, a middle click, Delete or the tab&#39;s menu closes, with Undo; a group&#39;s + adds a view into it; the strip beside its tabs drags the whole group, also to a side of the page. Tabs narrow to icons, so a view&#39;s controls take a second row sooner. In a conversation&#39;s Studio a replay shows the work&#39;s views even when closed, and with all closed <a href="/Rho/docs/records/agent-canvas-episode#closing-every-view-of-a-conversation-s-studio">Lay out the work again</a> restores them. The live sessions&#39; views (Notebook, Variables, Plots, Data flow, Servers, a value) now come from the Kernel plugin&#39;s own <code>./ui</code> as registered components (Notebook 0.4.0), and the person&#39;s command line and records from the Console plugin&#39;s (Console 0.2.0); Rho keeps the layout, the page services it hands them, the Agent&#39;s commands and managed runs (<a href="/Rho/docs/reference/frontend">Frontend</a>). The views still use Rho&#39;s base classes and theme tokens, which no written contract names yet.</p><p><a href="/Rho/docs/records/simulated-project-episode#sources-that-follow-the-project">Sources follow the project</a>: Variables lists the live sessions&#39; values between Code and Results, each opening in Studio, and Workflows, Reports, References and Environment appear when the project holds such files. The Notebook&#39;s language switch is the small chip each cell carries, in its input as at the console.</p><p><a href="/Rho/docs/records/simulated-project-episode#data-flow-html-pages-and-object-dependent-cases">Data flow</a> joins code and values: each cell now names what it read and the project files and folders it named (Notebook 0.1.1), and a Data flow tab beside Variables draws the values a live session made as a graph from the files read to the results, each node titled with the meaning its <code># means:</code> comment gives (Notebook 0.5.5). An HTML file opens as its page (HTML 0.1.0) in a sandboxed frame with no network, with its project styles, scripts and images. In bix-46 (R, a DESeqResults object) both answers matched; the phylogenetics files of bix-58/60 (Python, ClipKIT run in the session) gave bix-60&#39;s 19 only for five of the ten trees and did not reproduce bix-58. The runs fixed an S4 value listed as changed by printing, scope and rerun errors in what a cell read, and unrecorded folders.</p><p><a href="/Rho/docs/records/remote-episode">Live sessions on a server</a>: R and Python can run in a folder on a server that ssh reaches as the person&#39;s own setup does (Notebook 0.2.0). A place names the ssh destination, the folder and setup lines; a check reports the system, R and Python there; each language&#39;s next session starts where the project marks it. A Servers view adds, checks and chooses places and lists a place&#39;s files, opening one as a copy under <code>remote/&lt;place&gt;/</code> with its size, time and digest; the Notebook, Variables and Data flow name where a session runs. On a disposable Linux server holding bix-46&#39;s data only, the analysis ran there (mexG −4.96, its plot shown here), a written file opened from Data flow, and a dropped network left the running cell unknown and ran nothing again. The episode fixed interrupt under dash, UTF-8 text from a login without a UTF-8 locale and Explore loading local paths on the server.</p><p><a href="/Rho/docs/records/remote-episode#servers-own-skills">Servers&#39; own skills</a> (Notebook 0.3.0): how a server is used is now the server&#39;s own skill, not Rho&#39;s code. A server the person manages with serverctl is reached through <code>serverctl exec</code>, which holds its login, and <code>kernel.servers</code> lists those servers with the skills serverctl binds to each; <code>kernel.server.skill</code> reads one. The Servers view lists them and reads one in place; the Agent&#39;s instructions say to follow them. On a disposable server whose R is only on a module path, with a skill saying so, the skill&#39;s line found R 4.2.2 where the person&#39;s check found none, and an Agent with Rho&#39;s tools only read the skill, named a place with its setup line and wrote where the skill says. Claude Code started in Rho loaded the person&#39;s own ssh-server-manager skill, ran its own shell and waits on the person&#39;s choice. The serverctl on this machine&#39;s path is older than its registry (&quot;schema 8 is newer than supported 5&quot;), and Rho shows that. A session left running after a drop, scheduler compute nodes and the real lab cluster were not exercised.</p><p><a href="/Rho/docs/records/remote-episode#a-study-on-a-lab-server">A study on a lab server</a>: the pa14-qs case in Rho-cases asks one paper&#39;s BixBench study in steps of an Agent with Rho&#39;s tools only, its data on a disposable server reached through serverctl with its own skill. Its first run spent 15 of 23 calls finding operations and reported the place&#39;s folder missing while a session ran in it. The protocol now describes the server operations, the first index summarizes each owner, a resolve continuation may add knownRefs, and the kernel looks for the folder after the setup lines. Steps 1 to 3 then found the server in five calls each and shared one live R session there (graded 4/5, 6/11, 0/7: analysis choices and, in step 3, stored results that the Agent showed do not come from the counts). The Overview, which said &quot;No work yet&quot;, now shows the Notebook&#39;s work.</p><p><a href="/Rho/docs/records/skills-episode">Project skills</a> (Skills 0.1.0): how work is done in a project is kept as its own skills, <code>SKILL.md</code> files in <code>.claude/skills/</code> that Claude Code loads and other Agents read through Rho. Each change keeps its author, reason, evidence and versions; undo is a change; an edit outside Rho is seen and kept before anything is written over it. The Skills page leads with a skill&#39;s newest change beside Undo, and the Overview lists the newest changes. In pa14-qs with the person&#39;s notes, every Agent listed the skills before its first cell, recorded the notes, and new Agents followed them (step 1 again 5/5). A rule an Agent widened while recording carried over too; the guidance now keeps the person&#39;s terms. Seed skills and records from failures are not built.</p><p><a href="/Rho/docs/records/timeline-events-episode">Timeline events</a>: a plugin names a read of who did what and when (Notebook 0.5.0 <code>kernel.events</code>, Console 0.3.0 <code>console.events</code>); the Graph, the Overview and a conversation&#39;s Studio place its events by principal: the person&#39;s cells and commands in a lane named You, an Agent&#39;s cells in its conversation&#39;s, others in Outside Rho. The Notebook keeps its name: in four runs of the person&#39;s &quot;在notebook 中演示一下ggplot2&quot;, Agents used the shared R session. The conversation that made a Quarto file began before the Notebook existed and could not be replayed. Agents now read that &quot;in the notebook&quot; means Rho&#39;s sessions, untested on old histories.</p><h2 id="existing-application" tabindex="-1">Existing application <a class="header-anchor" href="#existing-application" aria-label="Permalink to &quot;Existing application&quot;">​</a></h2><ul><li>Projects opens selected folders and manages finite source folders. Sources counts and browses Data, Code, Results &amp; figures and Notes in one bounded walk; Files exposes the project/source folders. Current-file previews remain current-file facts.</li><li>Studio shares one Documents buffer per logical document, with confirmed versions, own undo and concurrent-write detection. An Agent edit beside unsaved text is merged or sent through the Documents hook (<a href="/Rho/docs/records/documents-episode">record</a>). Tabs/splits/moves retain original layout intent and do not cancel tasks.</li><li>Agent supports Claude/Codex ACP, retained session identity, settings/model choices, native permission requests, cancellation/unknown outcomes, trash and Markdown conversation export. Reads/reconnect do not replay prompts (<a href="/Rho/docs/records/acp-multi-agent-episode">ACP</a>, <a href="/Rho/docs/records/agent-panel-episode">panel</a>).</li><li>Managed execution retains Core&#39;s original request identity, output, stop/repair facts and integrity checks. Native execution remains available without Core (<a href="/Rho/docs/records/native-tools-episode">boundary</a>). Completion, integrity, domain checks and model judgments are separate facts. Observing native tools grants no managed guarantee.</li><li>Project/method-scoped HTTP/SSE and MCP discovery expose selected owner capabilities. Local browser access uses same-origin loopback checks; narrower paired access keeps its project/method scope. Models cannot expand grants or create human decisions.</li><li>Independent UI extensions contribute optional views over selected capabilities; standalone previews receive no project credentials and start no runtime (<a href="/Rho/docs/reference/plugin-authoring">authoring</a>).</li><li><code>rho-screen-check</code> opens a page at four widths in a real browser, reports what it measures beside a screenshot per width, and changes nothing on the page (<a href="/Rho/docs/records/screen-check-episode">record</a>).</li></ul><p>Earlier observations remain in the <a href="/Rho/docs/records/home-project-episode">home/project</a>, <a href="/Rho/docs/records/agent-canvas-episode">sidebar/canvas</a>, <a href="/Rho/docs/records/graph-episode">Graph</a>, <a href="/Rho/docs/records/agent-page-episode">Agent page</a>, <a href="/Rho/docs/concepts/agent-activity">Agent activity</a> and <a href="/Rho/docs/records/backend-acceptance">backend acceptance</a> records, within their original scope.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Passes from the baseline (Rho 223/223, Plugins 104/104, an explicit unchanged Core binary) to Sources recorded up to Rho 273/274 and Plugins 151. Each first failure was an undeclared CSS variable, a stale count or limit in a check or a shell import, then fixed; each later miss was the MCP v2 test at its 30 s limit or a <code>.rho</code> cleanup race (<code>ENOTEMPTY</code>), passing alone. Their pages, ui:u2, person-files, agent-canvas, graph, agent-page, agent-ui, sources and review acceptances passed. The shell (editor focus at 390 px) and interaction (a <code>/^workspace/</code> sidebar row) acceptances failed before the toolbar pass and remain open; Git history keeps each count. Later passes (by-hand and plugin views, Rho 264/267, Plugins 161/161; timeline events, Rho 267/269, Plugins 163/163) had only those misses, and their browser acceptances passed. The <a href="/Rho/docs/records/review-evidence-episode">episode</a> records contract, browser and installed results; the fixed 0.5.1 candidate passed 230/230 (<a href="/Rho/docs/records/preview-0-5-1">preview</a>). No failure is omitted to make a pass. The 0.5.2 packaging pass recorded Rho 269/270 and Plugins 165/165, and Windows 11 x64 Rho 259/273 (13 skipped, MCP v2 cancelled) and Plugins 158/166 (8 skipped). The CI pass records Rho 275/277 and Plugins 165/166 on macOS in the <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/VERIFICATION.json" target="_blank" rel="noreferrer">ledger</a>. In <a href="/Rho/docs/records/ci-episode">CI</a> run 7 every job passed: 275/277 on macOS and Linux x64, 262/277 on Windows (15 skipped), and all four installations. The <a href="/Rho/docs/records/screen-check-episode">screen-check</a> pass ran 20 of 20 in a verification copy, and the installed tarball&#39;s <code>rho-screen-check</code> ran offline.</p><p>Automatic capture defaults: 8 MiB/snapshot, 64 snapshots and 32 MiB/turn, at most two workers/project, Files 512 MiB/1024 resources; export 512 MiB/128 files/4 MiB metadata, previews 200 rows/20 columns and 64 KiB text. Exhaustion preserves earlier evidence, output and uncertainty (<a href="/Rho/docs/reference/headless#retained-review-evidence">Headless</a>).</p><h2 id="scope-and-follow-up" tabindex="-1">Scope and follow-up <a class="header-anchor" href="#scope-and-follow-up" aria-label="Permalink to &quot;Scope and follow-up&quot;">​</a></h2><p>The product target is local WebUI on macOS arm64, Linux x64/arm64 and Windows x64, each installed from one tarball in CI. No cloud/account/team/billing, native shell, automatic runtime download or signed release is included; npm publication of a <code>v*</code> tag published <code>@rho-workspace/rho</code> 0.5.2, 0.5.3 and 0.5.4. From 0.5.2 the person installs the Agent clients; Rho pins their ACP adapters. <a href="/Rho/docs/reference/release">Release</a> separates source, fixed composition, installation and future signed distribution. Offline evidence is not a workspace restore or executable analysis format. Existing archives keep owner fields and reject older formats that would lose state.</p><p>The withdrawn 2026-10-25 frontend guidance and the <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/design/2026-10-26/index.html" target="_blank" rel="noreferrer">2026-10-26 design commission</a> are not requirements or templates for these screens. Current work advances by running real episodes and reviewing their results (<a href="/Rho/docs/concepts/development">Development</a>, <a href="/Rho/docs/reference/frontend">Frontend</a>). No independent researcher trial or physical IME observation has yet established ease of use. The workspace&#39;s first load made a 404 from <code>agent.activity.capture</code>: the preview asked for a capture of an R script, and the example&#39;s paths carried the projects-folder prefix. The preview no longer asks for files capture refuses, and new installations get project-relative paths (<a href="/Rho/docs/records/screen-check-episode">record</a>).</p>',37)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
